@startuml

class Hospital {}

class Office {}

abstract class User {}

class Doctor extends User {}

class Patient extends User {}

class Schedule {
  + Date : date
  + StartTime : time
  + EndTime : time
}

class AppointmentType {
  + Name : string
  + Duration : int
}

class Appointment {
  + Date : date
  + StartTime : time
  + EndTime : time
}

Hospital "1" -- "1..*" Office
Doctor "1" -- "*" Schedule : creates
Office "1" -- "*" Schedule
Doctor "1" -- "*" Appointment : has
Patient "1" -- "*" Appointment : books
Schedule "1" -- "0..1" Appointment : is for
AppointmentType "1" -- "0..*" Appointment : is of type

enum AppointmentTypeEnum {
  BloodTest
  Consultation
  Surgery
}

class BloodTest extends AppointmentType {}
class ConsultationType extends AppointmentType {}
class Surgery extends AppointmentType {}

@enduml

